#!/usr/bin/env bash
# GSZ step122 — logged-in checkout. Signed-in customers aren't asked for email/
# WhatsApp; their account details are shown and used server-side. Safe + idempotent.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step122-$TS"; TMP=$(mktemp -d)
FILES=(routes/checkout.js views/checkout.ejs)
echo "==> step122: logged-in checkout"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/checkout.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/checkout.ejs','utf8'),{filename:'$GSZ/views/checkout.ejs'});console.log('    checkout.ejs ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
SLUG=$(cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "require('dotenv/config');const{Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:+(process.env.DB_PORT||5432),user:process.env.DB_USER,password:process.env.DB_PASS,database:process.env.DB_NAME});p.query(\"SELECT slug FROM products WHERE active AND NOT hidden ORDER BY id LIMIT 1\").then(function(r){console.log(r.rows[0]?r.rows[0].slug:'');return p.end();}).catch(function(){console.log('')})" 2>/dev/null || true)
if [ -n "$SLUG" ]; then CC=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3900/checkout?p=$SLUG&plan=0&region=PK" || true); [ "$CC" = "200" ] && echo "    checkout renders ($SLUG): OK" || { echo "    checkout $CC"; false; }; fi
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step122 OK ✅  Signed-in customers now see 'Delivering to your account' (email + WhatsApp) instead of empty fields; the order uses their account details."
